alter table public.suppliers add column if not exists kyc_expiry_date date; alter table public.suppliers add column if not exists kyc_reviewed_at timestamptz; alter table public.suppliers add column if not exists kyc_reviewed_by uuid references public.profiles(id);
create or replace function public.supplier_sensitive_update_guard() returns trigger language plpgsql set search_path=public as $$begin if current_user not in('postgres','service_role') and(new.status is distinct from old.status or new.kyc_status is distinct from old.kyc_status or new.kyc_expiry_date is distinct from old.kyc_expiry_date or new.kyc_reviewed_at is distinct from old.kyc_reviewed_at or new.kyc_reviewed_by is distinct from old.kyc_reviewed_by or new.currency is distinct from old.currency or new.payment_terms is distinct from old.payment_terms or new.account_manager_id is distinct from old.account_manager_id or new.rating is distinct from old.rating) then raise exception 'Sensitive supplier controls must use controlled supplier workflows.';end if;return new;end$$;
create or replace function public.supplier_set_kyc_v2(p_supplier_id uuid,p_kyc_status text,p_expiry_date date default null,p_reason text default null) returns public.suppliers language plpgsql security definer set search_path=public as $$declare v_row public.suppliers;v_old text;v_old_expiry date;begin if not public.supplier_can_control() then raise exception 'KYC control requires manager-level permission.';end if;if p_kyc_status not in('pending','approved','expired','rejected') then raise exception 'Invalid KYC status.';end if;if p_kyc_status='approved' and(p_expiry_date is null or p_expiry_date<=current_date) then raise exception 'Approved KYC requires a future expiry date.';end if;if p_kyc_status in('expired','rejected') and length(trim(coalesce(p_reason,'')))<5 then raise exception 'A reason of at least 5 characters is required.';end if;select * into v_row from public.suppliers where id=p_supplier_id for update;if not found then raise exception 'Supplier not found.';end if;v_old:=coalesce(v_row.kyc_status,'pending');v_old_expiry:=v_row.kyc_expiry_date;update public.suppliers set kyc_status=p_kyc_status,kyc_expiry_date=case when p_kyc_status='approved' then p_expiry_date else null end,kyc_reviewed_at=now(),kyc_reviewed_by=auth.uid(),updated_at=now() where id=p_supplier_id returning * into v_row;if p_kyc_status in('expired','rejected') and v_row.status='active' then update public.suppliers set status='pending',updated_at=now() where id=p_supplier_id returning * into v_row;end if;insert into public.supplier_events(supplier_id,event_type,from_value,to_value,reason,metadata,performed_by) values(p_supplier_id,'kyc_changed',v_old,p_kyc_status,nullif(trim(coalesce(p_reason,'')),''),jsonb_build_object('old_expiry',v_old_expiry,'new_expiry',case when p_kyc_status='approved' then p_expiry_date else null end),auth.uid());return v_row;end$$;
create or replace function public.supplier_set_status_v1(p_supplier_id uuid,p_status text,p_reason text default null) returns public.suppliers language plpgsql security definer set search_path=public as $$declare v_row public.suppliers;v_old text;begin if not public.supplier_can_control() then raise exception 'Supplier status control requires manager-level permission.';end if;if p_status not in('pending','active','inactive','blocked') then raise exception 'Invalid supplier status.';end if;if p_status in('inactive','blocked') and length(trim(coalesce(p_reason,'')))<5 then raise exception 'A reason of at least 5 characters is required.';end if;select * into v_row from public.suppliers where id=p_supplier_id for update;if not found then raise exception 'Supplier not found.';end if;if p_status='active' and(coalesce(v_row.kyc_status,'pending')<>'approved' or v_row.kyc_expiry_date is null or v_row.kyc_expiry_date<=current_date) then raise exception 'Supplier cannot be activated without valid, unexpired KYC approval.';end if;v_old:=v_row.status;update public.suppliers set status=p_status,updated_at=now() where id=p_supplier_id returning * into v_row;insert into public.supplier_events(supplier_id,event_type,from_value,to_value,reason,performed_by) values(p_supplier_id,'status_changed',v_old,p_status,nullif(trim(coalesce(p_reason,'')),''),auth.uid());return v_row;end$$;
revoke all on function public.supplier_set_kyc_v2(uuid,text,date,text) from public;grant execute on function public.supplier_set_kyc_v2(uuid,text,date,text) to authenticated,service_role;
